const i=[{id:"semptom-dispne",term:"Dispne",aliases:["dispne","dyspnea","dyspnoea","nefes darlığı","solunum güçlüğü"],normalizedTerm:"dispne",TurkishName:"Dispne",EnglishName:"Dyspnea",category:"Semptom",previewDefinition:"Nefes darlığı veya solunum güçlüğü hissidir.",preAnswerSafeDefinition:"Nefes darlığı veya solunum güçlüğü hissidir.",shortDefinition:"Nefes darlığı veya solunum güçlüğü hissidir.",detailedExplanation:"Dispne kardiyak, pulmoner, metabolik, hematolojik veya anksiyete ilişkili nedenlerle gelişebilir. Değerlendirmede başlangıç zamanı, eforla ilişkisi, ortopne, plöritik ağrı, wheezing, hipoksemi ve eşlik eden vital bulgular birlikte yorumlanır.",postAnswerExpandedExplanation:"Akut dispnede kalp yetmezliği, astım/KOAH alevlenmesi, pnömoni, pulmoner emboli, pnömotoraks, metabolik asidoz ve anksiyete ayırıcı tanıda düşünülür.",tusPearl:"Akut dispnede kardiyak, pulmoner, metabolik ve anksiyete ilişkili nedenler aynı anda ayırıcı tanıya alınmalıdır.",differentialPoint:"Ortopne kalp yetmezliğini, plöritik ağrı pulmoner emboli/pnömoniyi, wheezing astım veya KOAH alevlenmesini destekleyebilir.",clinicalRelevance:"Dispne, acil ve dahiliye sorularında ayırıcı tanı spektrumunu hızla genişleten temel başvuru semptomudur.",mechanism:"Solunum işi artışı, gaz değişim bozukluğu, hipoksemi, asidoz veya kardiyak dolum/basınç değişiklikleri dispne algısını tetikleyebilir.",relatedBranches:["pulmonology","cardiovascular","internal-medicine","emergency-medicine"],relatedTerms:["Ortopne","Wheezing","Pulmoner emboli"],difficulty:"kolay",keywordsForSearch:["nefes darlığı","solunum güçlüğü","akut dispne"]},{id:"enfeksiyon-tuberculosis",term:"Tüberküloz",aliases:["tüberküloz","tuberculosis","TB","verem","Mycobacterium tuberculosis"],normalizedTerm:"tuberkuloz",TurkishName:"Tüberküloz",EnglishName:"Tuberculosis",LatinName:"Mycobacterium tuberculosis infection",abbreviation:"TB",category:"Enfeksiyon hastalığı",previewDefinition:"Mycobacterium tuberculosis’in neden olduğu, çoğunlukla akciğeri tutan kronik granülomatöz enfeksiyondur.",preAnswerSafeDefinition:"Mycobacterium tuberculosis ile ilişkili kronik granülomatöz enfeksiyondur.",shortDefinition:"Mycobacterium tuberculosis’in neden olduğu, çoğunlukla akciğeri tutan kronik granülomatöz enfeksiyondur.",detailedExplanation:"Tüberküloz primer enfeksiyon, latent enfeksiyon veya reaktivasyon hastalığı şeklinde görülebilir. Akciğer tutulumu en sık olmakla birlikte lenf nodu, kemik, meninks ve genitoüriner sistem tutulumu da gelişebilir.",postAnswerExpandedExplanation:"Kronik öksürük, gece terlemesi, kilo kaybı, ateş ve hemoptizi birlikteliği aktif pulmoner tüberküloz açısından yüksek uyarıcıdır.",tusPearl:"Kronik öksürük + gece terlemesi + kilo kaybı + hemoptizi kombinasyonu tüberkülozu düşündürür.",differentialPoint:"Latent enfeksiyonda aktif semptom ve bulaştırıcılık beklenmez; aktif hastalıkta klinik bulgular ve bulaştırıcılık ön plandadır.",clinicalRelevance:"Granülomatöz enfeksiyon, kronik akciğer semptomu ve immünsüpresyon bağlamlarında sık sınanır.",mechanism:"Hücresel immün yanıt makrofaj aktivasyonu ve granülom oluşumu üzerinden enfeksiyonu sınırlamaya çalışır.",relatedBranches:["infectious-diseases","pulmonology","microbiology","pathology"],relatedTerms:["Kazeifiye granülom","Aside dirençli basil","Gece terlemesi"],difficulty:"orta",keywordsForSearch:["TB","verem","granülom","hemoptizi"]},{id:"elektrolit-hiperkalemi",term:"Hiperkalemi",aliases:["hiperkalemi","hyperkalemia","yüksek potasyum","serum potasyum yüksekliği"],normalizedTerm:"hiperkalemi",TurkishName:"Hiperkalemi",EnglishName:"Hyperkalemia",category:"Elektrolit bozukluğu",previewDefinition:"Serum potasyum düzeyinin normalin üzerine çıkmasıdır.",preAnswerSafeDefinition:"Serum potasyum düzeyinin normalin üzerine çıkmasıdır.",shortDefinition:"Serum potasyum düzeyinin normalin üzerine çıkmasıdır ve kardiyak iletimi etkileyebilir.",detailedExplanation:"Hiperkalemi böbrek yetmezliği, ilaçlar, asidoz, hücre yıkımı veya potasyum alım artışı ile gelişebilir. EKG değişikliği varsa acil yaklaşım önceliği değişir.",postAnswerExpandedExplanation:"EKG değişikliği bulunan hiperkalemide kardiyak membran stabilizasyonu acil önceliktir; potasyumu hücre içine kaydıran veya vücuttan uzaklaştıran tedaviler bunu izler.",tusPearl:"Hiperkalemi + EKG değişikliği varsa ilk basamak membran stabilizasyonudur.",differentialPoint:"Psödohiperkalemi hemolizli örnekte görülebilir; klinik ve EKG ile uyumsuzsa tekrar ölçüm düşünülür.",clinicalRelevance:"Aritmi ve ani kardiyak ölüm riski nedeniyle acil tedavi algoritmalarında yüksek değerli bir bulgudur.",mechanism:"Ekstrasellüler potasyum artışı membran potansiyelini değiştirerek miyokard eksitabilitesini ve iletimini bozar.",relatedBranches:["internal-medicine","emergency-medicine","cardiovascular","nephrology"],relatedTerms:["Sivri T dalgası","QRS genişlemesi","Kalsiyum glukonat"],difficulty:"kolay",keywordsForSearch:["potasyum","EKG","aritmi","böbrek yetmezliği"]},{id:"ekg-sivri-t-dalgasi",term:"Sivri T dalgası",aliases:["sivri T dalgası","çadır T dalgası","peaked T wave","tented T wave"],normalizedTerm:"sivri t dalgasi",TurkishName:"Sivri T dalgası",EnglishName:"Peaked T wave",category:"EKG bulgusu",previewDefinition:"EKG’de yüksek, dar tabanlı ve sivri T dalgası görünümüdür.",preAnswerSafeDefinition:"EKG’de yüksek, dar tabanlı ve sivri T dalgası görünümüdür.",shortDefinition:"EKG’de yüksek, dar tabanlı ve sivri T dalgası görünümüdür.",detailedExplanation:"Sivri T dalgası repolarizasyon morfolojisindeki değişimi ifade eder. Klinik bağlam ve serum elektrolitleriyle birlikte yorumlanmalıdır.",postAnswerExpandedExplanation:"Hiperkalemi bağlamında sivri T dalgası erken EKG bulgusu olabilir; daha ileri tabloda PR uzaması, QRS genişlemesi ve aritmi riski artar.",tusPearl:"Hiperkalemi + EKG değişikliği varsa ilk yaklaşım membran stabilizasyonu için intravenöz kalsiyum glukonattır.",differentialPoint:"İnsülin-glukoz potasyumu hücre içine kaydırır; ancak EKG değişikliği olan hastada ilk basamak kalsiyumdur.",clinicalRelevance:"Acil serviste hiperkalemiye bağlı kardiyak riskin fark edilmesini sağlar.",mechanism:"Ekstrasellüler K+ artışı kardiyak repolarizasyonu etkileyerek T dalgası morfolojisini değiştirir.",relatedBranches:["cardiovascular","internal-medicine","emergency-medicine"],relatedTerms:["Hiperkalemi","QRS genişlemesi","Kalsiyum glukonat"],difficulty:"orta",keywordsForSearch:["EKG","potasyum","çadır T","hiperkalemi"]},{id:"ekg-qrs-genislemesi",term:"QRS genişlemesi",aliases:["QRS genişlemesi","geniş QRS","wide QRS","QRS widening"],normalizedTerm:"qrs genislemesi",TurkishName:"QRS genişlemesi",EnglishName:"QRS widening",category:"EKG bulgusu",previewDefinition:"Ventriküler depolarizasyon süresinin uzadığını gösteren EKG bulgusudur.",preAnswerSafeDefinition:"Ventriküler depolarizasyon süresinin uzadığını gösteren EKG bulgusudur.",shortDefinition:"Ventriküler depolarizasyon süresinin uzadığını gösteren EKG bulgusudur.",detailedExplanation:"QRS genişlemesi iletim sisteminde gecikme, ventriküler ritim, elektrolit bozukluğu veya ilaç/toksin etkisiyle ortaya çıkabilir.",postAnswerExpandedExplanation:"Hiperkalemi ve trisiklik antidepresan toksisitesi gibi acil tablolarda QRS genişliği tedavi önceliğini değiştiren kritik bir EKG ipucudur.",tusPearl:"TCA zehirlenmesinde QRS genişlemesi varsa intravenöz sodyum bikarbonat düşünülür.",differentialPoint:"Hiperkalemide membran toksisitesi; TCA toksisitesinde hızlı sodyum kanal blokajı ön plandadır.",clinicalRelevance:"Toksikoloji, elektrolit bozukluğu ve aritmi sorularında acil tedavi seçimini belirler.",mechanism:"Miyokard veya iletim sistemindeki depolarizasyon yavaşladığında QRS süresi uzar.",relatedBranches:["cardiovascular","emergency-medicine","pharmacology"],relatedTerms:["Hiperkalemi","TCA toksisitesi","Sodyum bikarbonat"],difficulty:"orta",keywordsForSearch:["EKG","TCA","sodyum kanal blokajı","hiperkalemi"]},{id:"acil-kalsiyum-glukonat",term:"Kalsiyum glukonat",aliases:["kalsiyum glukonat","intravenöz kalsiyum glukonat","IV kalsiyum glukonat","calcium gluconate"],normalizedTerm:"kalsiyum glukonat",TurkishName:"Kalsiyum glukonat",EnglishName:"Calcium gluconate",abbreviation:"IV calcium",category:"Acil tedavi",previewDefinition:"Damar içi uygulanabilen kalsiyum preparatıdır.",preAnswerSafeDefinition:"Damar içi uygulanabilen kalsiyum preparatıdır.",shortDefinition:"Kardiyak membran stabilizasyonu için kullanılan intravenöz kalsiyum preparatıdır.",detailedExplanation:"Kalsiyum glukonat serum potasyumunu doğrudan düşürmez; miyokard hücrelerinin elektriksel instabilitesini geçici olarak azaltır. Potasyumu hücre içine kaydıran veya uzaklaştıran tedavilerden farklı bir basamaktır.",postAnswerExpandedExplanation:"Hiperkalemi + EKG değişikliği sorusunda ilk adım kalsiyum glukonattır; insülin-glukoz ve beta-agonistler potasyum kaydırma basamağıdır.",tusPearl:"Hiperkalemi + EKG değişikliği varsa ilk yaklaşım kalsiyum glukonattır.",differentialPoint:"Kalsiyum membranı stabilize eder; insülin-glukoz potasyumu hücre içine kaydırır, diyaliz potasyumu uzaklaştırır.",clinicalRelevance:"Acil tedavide “ilk basamak” ile “potasyumu düşüren basamak” ayrımını öğretir.",mechanism:"Kardiyak miyosit eşik potansiyelini stabilize ederek hiperkalemiye bağlı eksitabilite artışını azaltır.",relatedBranches:["internal-medicine","emergency-medicine","cardiovascular"],relatedTerms:["Hiperkalemi","Sivri T dalgası","İnsülin-glukoz"],difficulty:"kolay",keywordsForSearch:["hiperkalemi","EKG","membran stabilizasyonu","IV kalsiyum"]},{id:"asit-baz-anion-gap-metabolik-asidoz",term:"Anion gap metabolik asidoz",aliases:["anion gap metabolik asidoz","anyon açıklığı artmış metabolik asidoz","yüksek anyon açıklıklı metabolik asidoz","high anion gap metabolic acidosis","HAGMA"],normalizedTerm:"anion gap metabolik asidoz",TurkishName:"Yüksek anyon açıklıklı metabolik asidoz",EnglishName:"High anion gap metabolic acidosis",abbreviation:"HAGMA",category:"Asit-baz bozukluğu",previewDefinition:"Ölçülmeyen anyonların artışıyla gelişen metabolik asidoz tablosudur.",preAnswerSafeDefinition:"Ölçülmeyen anyonların artışıyla gelişen metabolik asidoz tablosudur.",shortDefinition:"Ölçülmeyen anyonların artışıyla gelişen metabolik asidoz tablosudur.",detailedExplanation:"Laktat, ketoasitler, üremik toksinler veya toksik alım ürünleri gibi ölçülmeyen anyonlar bikarbonat tamponunu tüketerek asidoz oluşturur.",postAnswerExpandedExplanation:"DKA, laktik asidoz, üremi ve toksik alımlar yüksek anyon açıklıklı metabolik asidozun klasik nedenleridir.",tusPearl:"Diyabetik ketoasidoz, laktik asidoz, üremi ve toksik alımlar klasik nedenlerdir.",differentialPoint:"Normal anyon açıklıklı asidozda bikarbonat kaybı veya renal tübüler asidoz daha olasıdır.",clinicalRelevance:"Asidoz mekanizmasını ayırarak DKA, sepsis, böbrek yetmezliği veya toksik alım olasılıklarını daraltır.",mechanism:"Ölçülmeyen asitlerin birikmesi bikarbonatı tüketir ve anyon açıklığını yükseltir.",relatedBranches:["internal-medicine","pediatrics","biochemistry"],relatedTerms:["Diyabetik ketoasidoz","Laktik asidoz","Renal tübüler asidoz"],difficulty:"orta",keywordsForSearch:["anyon açıklığı","metabolik asidoz","DKA","laktat"]},{id:"farmakoloji-desmopressin",term:"Desmopressin",aliases:["desmopressin","DDAVP","dezmopressin","sentetik ADH analoğu"],normalizedTerm:"desmopressin",TurkishName:"Dezmopressin",EnglishName:"Desmopressin",abbreviation:"DDAVP",category:"İlaç / ADH analoğu",previewDefinition:"V2 reseptör etkisi üzerinden böbrekte su geri emilimini artıran sentetik ADH analoğudur.",preAnswerSafeDefinition:"V2 reseptör etkisi üzerinden böbrekte su geri emilimini artıran sentetik ADH analoğudur.",shortDefinition:"V2 reseptör etkisi üzerinden böbrekte su geri emilimini artıran sentetik ADH analoğudur.",detailedExplanation:"Toplayıcı kanalda V2 reseptörlerini uyarır, aquaporin-2 yerleşimini artırır ve serbest su geri emilimini güçlendirir. Ayrıca vWF/faktör VIII salınımını artırmak için bazı kanama bozukluklarında kullanılabilir.",postAnswerExpandedExplanation:"Santral diabetes insipidusta ADH eksikliğini yerine koyar; nefrojenik diabetes insipidusta böbrek yanıtı bozuk olduğu için beklenen yanıt alınmaz.",tusPearl:"Santral diabetes insipidus tedavisinde kullanılır; nefrojenik diabetes insipidusta yanıt beklenmez.",differentialPoint:"Primer polidipside temel sorun ADH eksikliği değil aşırı su alımıdır.",clinicalRelevance:"Poliüri-polidipsi ayırıcı tanısında santral DI ile nefrojenik DI ayrımını öğretir.",mechanism:"V2 reseptör aktivasyonu cAMP/PKA aracılığıyla aquaporin-2 kanallarını apikal membrana taşır.",relatedBranches:["internal-medicine","pediatrics","pharmacology","physiology"],relatedTerms:["Santral diabetes insipidus","Nefrojenik diabetes insipidus","ADH"],difficulty:"orta",keywordsForSearch:["DI","ADH","V2 reseptör","poliüri"]},{id:"nefroloji-nefrotik-sendrom",term:"Nefrotik sendrom",aliases:["nefrotik sendrom","nephrotic syndrome","masif proteinüri"],normalizedTerm:"nefrotik sendrom",TurkishName:"Nefrotik sendrom",EnglishName:"Nephrotic syndrome",category:"Hastalık / sendrom",previewDefinition:"Masif proteinüri, hipoalbuminemi, ödem ve hiperlipidemi ile karakterize glomerüler sendromdur.",preAnswerSafeDefinition:"Masif proteinüri, hipoalbuminemi, ödem ve hiperlipidemi ile karakterize glomerüler sendromdur.",shortDefinition:"Masif proteinüri, hipoalbuminemi, ödem ve hiperlipidemi ile karakterize glomerüler sendromdur.",detailedExplanation:"Glomerüler filtrasyon bariyeri hasarı albumin kaybına yol açar; onkotik basınç azalır ve ödem gelişir. Karaciğerde lipoprotein sentezi arttığı için hiperlipidemi eşlik edebilir.",postAnswerExpandedExplanation:"Nefrotik sendromda proteinüri ve ödem ön plandadır; nefritik sendromda hematüri, hipertansiyon ve azotemi daha belirgindir.",tusPearl:"Çocukta ani başlayan ödem ve selektif albuminüri minimal değişiklik hastalığını düşündürür.",differentialPoint:"Nefritik sendromda hematüri/hipertansiyon; nefrotikte masif proteinüri/ödem baskındır.",clinicalRelevance:"Glomerüler sendrom ayrımını ve proteinüri tipini soru çözdürücü hale getirir.",mechanism:"Podosit veya filtrasyon bariyeri hasarı albumin geçirgenliğini artırır.",relatedBranches:["internal-medicine","pediatrics","pathology"],relatedTerms:["Minimal değişiklik hastalığı","Nefritik sendrom","Proteinüri"],difficulty:"kolay",keywordsForSearch:["proteinüri","ödem","hipoalbuminemi","minimal değişiklik"]},{id:"pediatri-reye-sendromu",term:"Reye sendromu",aliases:["Reye sendromu","Reye syndrome","aspirin ilişkili ensefalopati"],normalizedTerm:"reye sendromu",TurkishName:"Reye sendromu",EnglishName:"Reye syndrome",category:"Pediatrik sendrom",previewDefinition:"Çocuklarda akut ensefalopati ve karaciğer yağlanması ile seyreden nadir fakat ciddi tablodur.",preAnswerSafeDefinition:"Çocuklarda akut ensefalopati ve karaciğer yağlanması ile seyreden nadir fakat ciddi tablodur.",shortDefinition:"Çocuklarda viral enfeksiyon sırasında aspirin kullanımıyla ilişkilendirilen akut ensefalopati ve karaciğer yağlanması tablosudur.",detailedExplanation:"Mitokondriyal disfonksiyon karaciğerde mikroveziküler yağlanma ve hiperamonyemiye yol açabilir; klinikte kusma, bilinç değişikliği ve karaciğer fonksiyon bozukluğu görülebilir.",postAnswerExpandedExplanation:"Viral enfeksiyon geçiren çocukta aspirin kullanımı sonrası kusma, bilinç değişikliği ve karaciğer bulguları Reye sendromunu düşündürür.",tusPearl:"Viral enfeksiyonu olan çocukta aspirin sonrası ensefalopati + karaciğer bulguları Reye sendromunu düşündürür.",differentialPoint:"Akut viral hepatitte inflamasyon baskındır; Reye sendromunda ensefalopati ve mikroveziküler yağlanma vurgulanır.",clinicalRelevance:"Çocuklarda aspirin kontrendikasyonunun klinik gerekçesini öğretir.",mechanism:"Mitokondriyal yağ asidi oksidasyonu bozulur ve hepatik mikroveziküler steatoz gelişir.",relatedBranches:["pediatrics","pharmacology","pathology"],relatedTerms:["Aspirin","Hiperamonyemi","Mikroveziküler steatoz"],difficulty:"orta",keywordsForSearch:["aspirin","viral enfeksiyon","ensefalopati","çocuk"]},{id:"dermatoloji-perioral-dermatit",term:"Perioral dermatit",aliases:["perioral dermatit","perioral dermatitis","ağız çevresi dermatiti"],normalizedTerm:"perioral dermatit",TurkishName:"Perioral dermatit",EnglishName:"Perioral dermatitis",category:"Dermatolojik hastalık",previewDefinition:"Ağız çevresinde papül/püstül ve eritemle seyreden inflamatuvar dermatit tablosudur.",preAnswerSafeDefinition:"Ağız çevresinde papül/püstül ve eritemle seyreden inflamatuvar dermatit tablosudur.",shortDefinition:"Ağız çevresinde papül/püstül ve eritemle seyreden inflamatuvar dermatit tablosudur.",detailedExplanation:"Topikal steroid kullanımıyla tetiklenebilir veya kötüleşebilir. Lezyonlar genellikle vermilion sınırını görece korur.",postAnswerExpandedExplanation:"Perioral dermatitte topikal steroidler tabloyu kötüleştirebilir; rozasea ve akne ile ayırıcı tanı önemlidir.",tusPearl:"Ağız çevresi papül-püstül + topikal steroid öyküsü perioral dermatiti düşündürür.",differentialPoint:"Akne komedonlarla, rozasea flushing/telangiektazi ile daha çok ilişkilidir.",clinicalRelevance:"Dermatoloji sorularında lezyon dağılımı ve ilaç öyküsünü bağlamayı sağlar.",mechanism:"Cilt bariyeri ve foliküler inflamasyonun bozulması perioral lezyonlara katkı sağlar.",relatedBranches:["dermatology","pharmacology"],relatedTerms:["Topikal steroid","Rozasea","Akne"],difficulty:"orta",keywordsForSearch:["ağız çevresi","steroid","papül","püstül"]},{id:"kardiyoloji-pulsus-paradoxus",term:"Pulsus paradoxus",aliases:["pulsus paradoxus","paradoks nabız","pulsus paradoksus"],normalizedTerm:"pulsus paradoxus",TurkishName:"Paradoks nabız",LatinName:"Pulsus paradoxus",category:"Fizik muayene bulgusu",previewDefinition:"İnspirasyon sırasında sistolik kan basıncında belirgin düşüş olmasıdır.",preAnswerSafeDefinition:"İnspirasyon sırasında sistolik kan basıncında belirgin düşüş olmasıdır.",shortDefinition:"İnspirasyon sırasında sistolik kan basıncında belirgin düşüş olmasıdır.",detailedExplanation:"Klasik olarak inspirasyonda sistolik basıncın 10 mmHg’den fazla azalması şeklinde tanımlanır. Kardiyak tamponad ve ağır obstrüktif akciğer hastalığı bağlamında önemlidir.",postAnswerExpandedExplanation:"Hipotansiyon, juguler venöz dolgunluk ve boğuk kalp sesleriyle birlikteyse kardiyak tamponad lehine güçlü ipucudur.",tusPearl:"Beck triadı + pulsus paradoxus kardiyak tamponadı düşündürür.",differentialPoint:"Konstriktif perikarditte Kussmaul bulgusu daha tipiktir; tamponadda pulsus paradoxus ön plana çıkar.",clinicalRelevance:"Şok ve perikard hastalığı sorularında fizik muayene ipucudur.",mechanism:"İnspirasyonda sağ kalp dolumu artar, interventriküler septum sola kayar ve sol ventrikül atım hacmi azalır.",relatedBranches:["cardiovascular","emergency-medicine","pulmonology"],relatedTerms:["Kardiyak tamponad","Beck triadı","Kussmaul bulgusu"],difficulty:"orta",keywordsForSearch:["tamponad","inspirasyon","sistolik basınç"]},{id:"enfeksiyon-step-ladder-fever",term:"Step-ladder fever",aliases:["step-ladder fever","basamaklı ateş","merdiven tarzı ateş"],normalizedTerm:"step ladder fever",TurkishName:"Basamaklı ateş",EnglishName:"Step-ladder fever",category:"Klinik ipucu",previewDefinition:"Ateşin günler içinde kademeli yükselme paterni göstermesidir.",preAnswerSafeDefinition:"Ateşin günler içinde kademeli yükselme paterni göstermesidir.",shortDefinition:"Ateşin günler içinde kademeli yükselme paterni göstermesidir.",detailedExplanation:"Klinik pratikte ateş paternleri tek başına tanı koydurmaz; ancak seyahat, gastrointestinal semptomlar ve temas öyküsüyle birlikte anlam kazanır.",postAnswerExpandedExplanation:"Tifo/paratifo gibi enterik ateş tablolarında klasik olarak basamaklı ateş paterni öğretici bir ipucu olarak kullanılır.",tusPearl:"Basamaklı ateş + karın yakınmaları + rölatif bradikardi enterik ateşi düşündürebilir.",differentialPoint:"Malaryada periyodik ateş paternleri, brusellozda dalgalı ateş anlatımı daha tipiktir.",clinicalRelevance:"Enfeksiyon sorularında ateş paterniyle etken/hastalık daraltmayı sağlar.",mechanism:"Sistemik enfeksiyon yanıtının günler içinde artan sitokin cevabıyla seyretmesi ateş paternini etkileyebilir.",relatedBranches:["infectious-diseases","microbiology"],relatedTerms:["Tifo","Salmonella Typhi","Rölatif bradikardi"],difficulty:"orta",keywordsForSearch:["tifo","ateş paterni","enterik ateş"]},{id:"hepatobiliyer-charcot-triadi",term:"Charcot triadı",aliases:["Charcot triadı","Charcot triad","ateş sarılık sağ üst kadran ağrısı"],normalizedTerm:"charcot triadi",TurkishName:"Charcot triadı",EnglishName:"Charcot triad",category:"Klinik triad",previewDefinition:"Ateş, sarılık ve sağ üst kadran ağrısı birlikteliğidir.",preAnswerSafeDefinition:"Ateş, sarılık ve sağ üst kadran ağrısı birlikteliğidir.",shortDefinition:"Ateş, sarılık ve sağ üst kadran ağrısı birlikteliğidir.",detailedExplanation:"Triad hepatobiliyer enfeksiyon ve obstrüksiyon bağlamında değerlendirilir. Hipotansiyon ve bilinç değişikliği eklenirse daha ağır tablo düşünülür.",postAnswerExpandedExplanation:"Charcot triadı akut kolanjit için klasik ipucudur; Reynolds pentadı ağır/septik tabloyu düşündürür.",tusPearl:"Ateş + sarılık + sağ üst kadran ağrısı akut kolanjit açısından yüksek değerli ipucudur.",differentialPoint:"Kolesistitte sarılık genellikle baskın değildir; kolanjitte safra yolu obstrüksiyonu ve enfeksiyon birliktedir.",clinicalRelevance:"Hepatobiliyer acillerde erken tanı ve antibiyotik/drenaj yaklaşımını belirler.",mechanism:"Safra yolu obstrüksiyonu üzerine bakteriyel enfeksiyon eklenmesi sistemik inflamasyon ve kolestaz bulguları oluşturur.",relatedBranches:["general-surgery","internal-medicine","infectious-diseases"],relatedTerms:["Akut kolanjit","Reynolds pentadı","Koledok taşı"],difficulty:"kolay",keywordsForSearch:["kolanjit","sarılık","sağ üst kadran","ateş"]},{id:"hematoloji-virchow-triadi",term:"Virchow triadı",aliases:["Virchow triadı","Virchow triad","staz endotelyal hasar hiperkoagülabilite"],normalizedTerm:"virchow triadi",TurkishName:"Virchow triadı",EnglishName:"Virchow triad",category:"Patofizyolojik triad",previewDefinition:"Tromboza yatkınlığı açıklayan staz, endotelyal hasar ve hiperkoagülabilite üçlüsüdür.",preAnswerSafeDefinition:"Tromboza yatkınlığı açıklayan staz, endotelyal hasar ve hiperkoagülabilite üçlüsüdür.",shortDefinition:"Tromboza yatkınlığı açıklayan staz, endotelyal hasar ve hiperkoagülabilite üçlüsüdür.",detailedExplanation:"Venöz tromboembolide immobilizasyon stazı, cerrahi/travma endotelyal hasarı ve malignite/gebelik/kalıtsal trombofililer hiperkoagülabiliteyi temsil eder.",postAnswerExpandedExplanation:"DVT ve pulmoner emboli sorularında risk faktörlerini tek mekanik çatı altında toplar.",tusPearl:"Postoperatif immobilizasyon, malignite ve gebelik gibi durumlar Virchow triadı üzerinden VTE riskini artırır.",differentialPoint:"Arteriyel trombozda aterosklerotik plak rüptürü ve trombosit aktivasyonu daha baskınken venöz trombozda staz/hiperkoagülabilite öne çıkar.",clinicalRelevance:"DVT/PE risk faktörlerinin mekanizma temelli yorumlanmasını sağlar.",mechanism:"Kan akımının yavaşlaması, damar duvarı hasarı ve pıhtılaşma eğilimi trombüs oluşumunu kolaylaştırır.",relatedBranches:["hematology","pulmonology","general-surgery","obstetrics-gynecology"],relatedTerms:["Derin ven trombozu","Pulmoner emboli","Hiperkoagülabilite"],difficulty:"kolay",keywordsForSearch:["tromboz","VTE","staz","hiperkoagülabilite"]},{id:"patoloji-reed-sternberg-hucresi",term:"Reed-Sternberg hücresi",aliases:["Reed-Sternberg hücresi","Reed Sternberg hücresi","RS hücresi","owl-eye cell"],normalizedTerm:"reed sternberg hucresi",TurkishName:"Reed-Sternberg hücresi",EnglishName:"Reed-Sternberg cell",category:"Histopatolojik terim",previewDefinition:"Çift çekirdekli veya belirgin nükleollü büyük atipik hücre görünümüdür.",preAnswerSafeDefinition:"Çift çekirdekli veya belirgin nükleollü büyük atipik hücre görünümüdür.",shortDefinition:"Çift çekirdekli veya belirgin nükleollü büyük atipik hücre görünümüdür.",detailedExplanation:"Klasik Hodgkin lenfomada tanısal değeri olan büyük B hücre kökenli atipik hücrelerdir. İmmünfenotip ve klinik bağlamla birlikte değerlendirilir.",postAnswerExpandedExplanation:"Ağrısız lenfadenopati, B semptomları ve Reed-Sternberg hücresi birlikteliği Hodgkin lenfoma lehine güçlü ipucudur.",tusPearl:"Reed-Sternberg hücresi klasik Hodgkin lenfomanın histolojik anahtar bulgusudur.",differentialPoint:"Non-Hodgkin lenfomalar genellikle farklı hücresel patern ve yayılım özellikleriyle değerlendirilir.",clinicalRelevance:"Lenfoma sorularında histoloji-klinik bağını kurar.",mechanism:"Germinal merkez B hücrelerinden köken alan neoplastik hücrelerin karakteristik morfolojik görünümüdür.",relatedBranches:["pathology","hematology","internal-medicine"],relatedTerms:["Hodgkin lenfoma","B semptomları","Lenfadenopati"],difficulty:"kolay",keywordsForSearch:["Hodgkin","owl eye","lenfoma","histoloji"]},{id:"patoloji-kazeifiye-granulom",term:"Kazeifiye granülom",aliases:["kazeifiye granülom","caseating granuloma","kazeöz nekrozlu granülom","caseous granuloma"],normalizedTerm:"kazeifiye granulom",TurkishName:"Kazeifiye granülom",EnglishName:"Caseating granuloma",category:"Histopatolojik terim",previewDefinition:"Merkezinde kazeöz nekroz bulunan granülomatöz inflamasyon görünümüdür.",preAnswerSafeDefinition:"Merkezinde kazeöz nekroz bulunan granülomatöz inflamasyon görünümüdür.",shortDefinition:"Merkezinde kazeöz nekroz bulunan granülomatöz inflamasyon görünümüdür.",detailedExplanation:"Makrofajların epiteloid histiyositlere dönüşmesi ve çevresinde lenfositlerin yer almasıyla granülom oluşur; merkezde kazeöz nekroz varsa kazeifiye granülom denir.",postAnswerExpandedExplanation:"Tüberküloz ve bazı fungal enfeksiyonlarda kazeifiye granülom klasik histopatolojik ipucudur.",tusPearl:"Kazeifiye granülom + aside dirençli basil tüberküloz lehine yüksek değerli kombinasyondur.",differentialPoint:"Sarkoidozda genellikle non-kazeifiye granülom beklenir.",clinicalRelevance:"Granülomatöz hastalıkların ayırıcı tanısında patoloji bulgusunu anlamlandırır.",mechanism:"Tip IV hücresel immün yanıt kronik antijeni makrofaj/lenfosit ağıyla sınırlamaya çalışır.",relatedBranches:["pathology","microbiology","infectious-diseases"],relatedTerms:["Tüberküloz","Aside dirençli basil","Non-kazeifiye granülom"],difficulty:"orta",keywordsForSearch:["granülom","tüberküloz","kazeöz nekroz","sarkoidoz"]},{id:"biyokimya-ast-alt-orani",term:"AST/ALT oranı",aliases:["AST/ALT oranı","AST ALT oranı","De Ritis oranı","AST/ALT ratio"],normalizedTerm:"ast alt orani",TurkishName:"AST/ALT oranı",EnglishName:"AST/ALT ratio",category:"Laboratuvar parametresi",previewDefinition:"Serum AST düzeyinin ALT düzeyine oranını ifade eden karaciğer enzim yorumudur.",preAnswerSafeDefinition:"Serum AST düzeyinin ALT düzeyine oranını ifade eden karaciğer enzim yorumudur.",shortDefinition:"Serum AST düzeyinin ALT düzeyine oranını ifade eden karaciğer enzim yorumudur.",detailedExplanation:"AST karaciğer dışında kas ve diğer dokularda da bulunur; ALT karaciğere daha özgüdür. Oran, klinik bağlama göre hepatoselüler hasarın nedenini yorumlamada yardımcıdır.",postAnswerExpandedExplanation:"AST/ALT oranının 2’den büyük olması alkol ilişkili karaciğer hastalığı lehine klasik bir ipucudur; tek başına tanı koydurmaz.",tusPearl:"AST/ALT > 2 alkolik hepatit/alkol ilişkili karaciğer hastalığı açısından klasik TUS ipucudur.",differentialPoint:"Viral hepatitlerde ALT artışı çoğu zaman daha belirgindir; kas hasarında AST de yükselebilir.",clinicalRelevance:"Karaciğer enzim paternlerinin etiyolojiyle ilişkilendirilmesini sağlar.",mechanism:"Alkol ilişkili mitokondriyal hasar AST artışını görece belirginleştirebilir.",relatedBranches:["internal-medicine","biochemistry","gastroenterology"],relatedTerms:["Alkolik hepatit","Transaminaz","Hepatoselüler hasar"],difficulty:"orta",keywordsForSearch:["AST","ALT","De Ritis","alkol"]},{id:"biyokimya-indirekt-hiperbilirubinemi",term:"İndirekt hiperbilirubinemi",aliases:["indirekt hiperbilirubinemi","unkonjuge hiperbilirubinemi","indirect hyperbilirubinemia","unconjugated hyperbilirubinemia"],normalizedTerm:"indirekt hiperbilirubinemi",TurkishName:"İndirekt hiperbilirubinemi",EnglishName:"Indirect hyperbilirubinemia",category:"Laboratuvar parametresi",previewDefinition:"Konjuge olmamış bilirubinin serumda artmasıdır.",preAnswerSafeDefinition:"Konjuge olmamış bilirubinin serumda artmasıdır.",shortDefinition:"Konjuge olmamış bilirubinin serumda artmasıdır.",detailedExplanation:"Hemoliz, bilirubin alım/konjugasyon bozuklukları veya yenidoğan fizyolojisi indirekt bilirubin artışına yol açabilir. İdrarda bilirubin görülmesi genellikle konjuge bilirubin artışını düşündürür.",postAnswerExpandedExplanation:"Hemoliz ve Gilbert sendromu indirekt hiperbilirubinemi; safra yolu obstrüksiyonu ise daha çok direkt hiperbilirubinemi ile ilişkilidir.",tusPearl:"Hemoliz + indirekt bilirubin artışı + retikülositoz hemolitik süreci destekler.",differentialPoint:"Direkt hiperbilirubinemi suda çözünebildiği için idrar bilirubiniyle ilişkilidir; indirekt bilirubin idrara geçmez.",clinicalRelevance:"Sarılık sorularında prehepatik, hepatik ve posthepatik ayrımı yapmayı kolaylaştırır.",mechanism:"Bilirubinin konjugasyon öncesi formunun üretimi artar veya hepatik konjugasyonu yetersiz kalır.",relatedBranches:["biochemistry","pediatrics","internal-medicine","hematology"],relatedTerms:["Hemoliz","Gilbert sendromu","Direkt hiperbilirubinemi"],difficulty:"orta",keywordsForSearch:["bilirubin","hemoliz","sarılık","Gilbert"]},{id:"mikrobiyoloji-koagulaz",term:"Koagülaz",aliases:["koagülaz","coagulase","koagulaz","koagülaz pozitif"],normalizedTerm:"koagulaz",TurkishName:"Koagülaz",EnglishName:"Coagulase",category:"Mikrobiyoloji testi",previewDefinition:"Stafilokok türlerini ayırmada kullanılan plazmayı pıhtılaştırma enzimi/testidir.",preAnswerSafeDefinition:"Stafilokok türlerini ayırmada kullanılan plazmayı pıhtılaştırma enzimi/testidir.",shortDefinition:"Stafilokok türlerini ayırmada kullanılan plazmayı pıhtılaştırma enzimi/testidir.",detailedExplanation:"Koagülaz pozitiflik klasik olarak Staphylococcus aureus lehinedir; koagülaz negatif stafilokoklar kateter/protez ilişkili enfeksiyonlarda önem kazanabilir.",postAnswerExpandedExplanation:"Staphylococcus aureus koagülaz pozitif; S. epidermidis ve S. saprophyticus genellikle koagülaz negatiftir.",tusPearl:"Gram pozitif kok kümeleri + koagülaz pozitiflik Staphylococcus aureus lehinedir.",differentialPoint:"S. epidermidis novobiyosine duyarlı, S. saprophyticus novobiyosine dirençlidir.",clinicalRelevance:"Mikrobiyoloji sorularında etken ayrımını hızlandırır.",mechanism:"Fibrinojeni fibrine dönüştürerek bakterinin konak savunmasından kaçmasına katkı sağlayabilir.",relatedBranches:["microbiology","infectious-diseases"],relatedTerms:["Staphylococcus aureus","Novobiyosin","Gram pozitif kok"],difficulty:"kolay",keywordsForSearch:["stafilokok","S aureus","koagülaz pozitif"]},{id:"farmakoloji-nalokson",term:"Nalokson",aliases:["nalokson","naloxone","opioid antagonisti"],normalizedTerm:"nalokson",TurkishName:"Nalokson",EnglishName:"Naloxone",category:"Antidot",previewDefinition:"Opioid reseptörlerini bloke eden antagonist ilaçtır.",preAnswerSafeDefinition:"Opioid reseptörlerini bloke eden antagonist ilaçtır.",shortDefinition:"Opioid reseptör antagonisti olarak opioid toksisitesinde solunum depresyonunu geri çevirmek için kullanılır.",detailedExplanation:"Nalokson miyoza, bilinç baskılanmasına ve solunum depresyonuna eşlik eden opioid zehirlenmesi tablosunda acil antidot olarak önemlidir. Etki süresi bazı opioidlerden kısa olabilir.",postAnswerExpandedExplanation:"Opioid toksisitesi triadı: bilinç baskılanması, miyozis ve solunum depresyonudur; antidot naloksondur.",tusPearl:"Opioid toksisitesi triadında antidot naloksondur.",differentialPoint:"Benzodiazepin toksisitesinde flumazenil teorik antidottur; nöbet riski nedeniyle her hastada rutin kullanılmaz.",clinicalRelevance:"Zehirlenme sorularında toksidromdan antidota gitmeyi sağlar.",mechanism:"µ-opioid reseptörlerini kompetitif olarak bloke eder.",relatedBranches:["pharmacology","emergency-medicine"],relatedTerms:["Opioid toksisitesi","Miyozis","Solunum depresyonu"],difficulty:"kolay",keywordsForSearch:["opioid","antidot","miyozis","solunum depresyonu"]},{id:"acil-anafilaksi-epinefrin",term:"İntramüsküler epinefrin",aliases:["intramüsküler epinefrin","IM epinefrin","intramuskuler epinefrin","adrenalin","epinefrin"],normalizedTerm:"intramuskuler epinefrin",TurkishName:"İntramüsküler epinefrin",EnglishName:"Intramuscular epinephrine",abbreviation:"IM epinephrine",category:"Acil tedavi",previewDefinition:"Alfa ve beta adrenerjik reseptörleri uyaran sempatomimetik ilaçtır.",preAnswerSafeDefinition:"Alfa ve beta adrenerjik reseptörleri uyaran sempatomimetik ilaçtır.",shortDefinition:"Anafilakside ilk ve hayat kurtarıcı tedavi olarak kullanılan alfa/beta adrenerjik agonisttir.",detailedExplanation:"Epinefrin bronkodilatasyon, vazokonstriksiyon ve mast hücre mediyatör salınımını azaltma etkileriyle anafilaksinin temel sonuçlarını hedefler. Antihistaminik ve steroidler destekleyicidir.",postAnswerExpandedExplanation:"Anafilakside ilk tedavi IM epinefrindir; antihistaminik veya steroid ilk basamağın yerine geçmez.",tusPearl:"Anafilakside ilk tedavi IM epinefrindir.",differentialPoint:"Vazovagal senkopta bradikardi/solukluk; anafilakside ürtiker, bronkospazm, hipotansiyon veya anjiyoödem beklenir.",clinicalRelevance:"Acil tedavide “önce ne yapılır?” sorularının en yüksek değerli karar noktalarından biridir.",mechanism:"α1 vazokonstriksiyon, β2 bronkodilatasyon ve mast hücre mediyatör salınımını azaltıcı etki sağlar.",relatedBranches:["emergency-medicine","immunology","pharmacology"],relatedTerms:["Anafilaksi","Ürtiker","Bronkospazm"],difficulty:"kolay",keywordsForSearch:["anafilaksi","adrenalin","acil tedavi"]},{id:"endokrin-diyabetik-ketoasidoz",term:"Diyabetik ketoasidoz",aliases:["diyabetik ketoasidoz","DKA","diabetic ketoacidosis"],normalizedTerm:"diyabetik ketoasidoz",TurkishName:"Diyabetik ketoasidoz",EnglishName:"Diabetic ketoacidosis",abbreviation:"DKA",category:"Endokrin acil",previewDefinition:"İnsülin eksikliğiyle ilişkili hiperglisemi, ketozis ve metabolik asidoz tablosudur.",preAnswerSafeDefinition:"İnsülin eksikliğiyle ilişkili hiperglisemi, ketozis ve metabolik asidoz tablosudur.",shortDefinition:"İnsülin eksikliğiyle ilişkili hiperglisemi, ketozis ve metabolik asidoz tablosudur.",detailedExplanation:"Mutlak veya göreceli insülin eksikliği lipoliz ve ketogenezisi artırır; ozmotik diürez sıvı-elektrolit kaybına yol açar.",postAnswerExpandedExplanation:"DKA tedavisinde sıvı replasmanı önceliklidir; insülin başlanmadan önce potasyum düzeyi değerlendirilmelidir.",tusPearl:"DKA’da ilk yaklaşım sıvı replasmanıdır; K+ düşükse insülin geciktirilip potasyum düzeltilir.",differentialPoint:"HHS’de ketozis belirgin değildir ve osmolalite çok yüksek olabilir; DKA’da ketozis/asidoz ön plandadır.",clinicalRelevance:"Endokrin acillerde tedavi sırası ve potasyum güvenliği açısından kritiktir.",mechanism:"İnsülin eksikliği lipolizi artırır; serbest yağ asitleri keton cisimlerine dönüşür ve asidoz oluşturur.",relatedBranches:["internal-medicine","emergency-medicine","biochemistry"],relatedTerms:["Anion gap metabolik asidoz","Keton","Potasyum"],difficulty:"orta",keywordsForSearch:["DKA","ketozis","hiperglisemi","potasyum"]}];export{i as T};
